package com.gmail.nossr50.util;

import com.gmail.nossr50.api.ItemSpawnReason;
import com.gmail.nossr50.datatypes.player.McMMOPlayer;
import com.gmail.nossr50.mcMMO;
import com.gmail.nossr50.runnables.player.PlayerProfileLoadingTask;
import com.gmail.nossr50.util.player.UserManager;
import com.google.common.collect.ImmutableSet;
import org.bukkit.Location;
import org.bukkit.block.BlockState;
import org.bukkit.entity.*;
import org.bukkit.inventory.ItemStack;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

import java.util.Collection;
import java.util.Locale;
import java.util.Random;
import java.util.Set;
import java.util.function.Predicate;

public final class Misc {
    private static final @NotNull Random random = new Random();

    public static final int TIME_CONVERSION_FACTOR = 1000;
    public static final int TICK_CONVERSION_FACTOR = 20;

    public static final int PLAYER_RESPAWN_COOLDOWN_SECONDS = 5;
    public static final double SKILL_MESSAGE_MAX_SENDING_DISTANCE = 10.0;

    public static final @NotNull Set<String> modNames = ImmutableSet.of("LOTR", "BUILDCRAFT", "ENDERIO", "ENHANCEDBIOMES", "IC2", "METALLURGY", "FORESTRY", "GALACTICRAFT", "RAILCRAFT", "TWILIGHTFOREST", "THAUMCRAFT", "GRAVESTONEMOD", "GROWTHCRAFT", "ARCTICMOBS", "DEMONMOBS", "INFERNOMOBS", "SWAMPMOBS", "MARICULTURE", "MINESTRAPPOLATION");

    private Misc() {}

    public static boolean isNear(@NotNull Location first, @NotNull Location second, double maxDistance) {
        return (first.getWorld() == second.getWorld()) && (first.distanceSquared(second) < (maxDistance * maxDistance) || maxDistance == 0);
    }

    public static Location getBlockCenter(BlockState blockState) {
        return blockState.getLocation().add(0.5, 0.5, 0.5);
    }

    public static void profileCleanup(@NotNull String playerName) {
        Player player = mcMMO.p.getServer().getPlayerExact(playerName);

        if (player != null) {
            UserManager.remove(player);
            mcMMO.p.getFoliaLib().getImpl().runLaterAsync(new PlayerProfileLoadingTask(player), 1);
        }
    }

    public static void printProgress(int convertedUsers, int progressInterval, long startMillis) {
        if ((convertedUsers % progressInterval) == 0) {
            mcMMO.p.getLogger().info(String.format("Conversion progress: %d users at %.2f users/second", convertedUsers, convertedUsers / (double) ((System.currentTimeMillis() - startMillis) / TIME_CONVERSION_FACTOR)));
        }
    }

    public static String getModName(@NotNull String materialName) {
        for (String mod : modNames) {
            if (materialName.contains(mod)) {
                return mod;
            }
        }

        String[] materialSplit = materialName.split("_");
        if (materialSplit.length > 1) {
            return materialSplit[0].toLowerCase(Locale.ENGLISH);
        }

        return "UnknownMods";
    }

    public static Location getLocationOffset(@NotNull Location location, double strength) {
        double blockX = location.getBlockX();
        double blockZ = location.getBlockZ();

        double distance = strength * random.nextDouble();
        blockX = random.nextBoolean() ? blockX + distance : blockX - distance;

        distance = strength * random.nextDouble();
        blockZ = random.nextBoolean() ? blockZ + distance : blockZ - distance;

        return new Location(location.getWorld(), blockX, location.getY(), blockZ);
    }

    public static @NotNull Random getRandom() {
        return random;
    }

    public static boolean isPartyLeader(@NotNull McMMOPlayer mmoPlayer) {
        return mmoPlayer.getParty().getLeader().getUniqueId().equals(mmoPlayer.getPlayer().getUniqueId());
    }

    public static void spawnExperienceOrb(@NotNull Location location, int experienceValue) {
        if (location.getWorld() == null)
            return;

        ExperienceOrb experienceOrb = (ExperienceOrb) location.getWorld().spawnEntity(location, EntityType.EXPERIENCE_ORB);
        experienceOrb.setExperience(experienceValue);
    }

    public static void spawnItemsFromCollection(Player player, Location location, Collection<ItemStack> items, ItemSpawnReason reason) {
        MiscItemSpawner.spawnItemsFromCollection(player, location, items, reason);
    }

    public static void spawnItemsFromCollection(Player player, Location location, Collection<ItemStack> items, ItemSpawnReason reason, int delay) {
        MiscItemSpawner.spawnItemsFromCollection(player, location, items, reason, delay);
    }

    public static Item spawnItem(Collection<ItemStack> items, ItemSpawnReason reason, Location location, Predicate<String> predicate, Player player) {
        return MiscItemSpawner.spawnItem(items, reason, location, predicate, player);
    }

    public static Item spawnItem(ItemStack item, ItemSpawnReason reason, Location location, Predicate<String> predicate, Player player) {
        return MiscItemSpawner.spawnItem(item, reason, location, predicate, player);
    }

    public static void spawnItems(Player player, Location location, ItemStack item, int amount, ItemSpawnReason reason) {
        MiscItemSpawner.spawnItems(player, location, item, amount, reason);
    }

    public static Item spawnItem(Player player, Location location, ItemStack item, ItemSpawnReason reason) {
        return MiscItemSpawner.spawnItem(player, location, item, reason);
    }

    public static Item spawnItemNaturally(Player player, Location location, ItemStack item, ItemSpawnReason reason) {
        return MiscItemSpawner.spawnItemNaturally(player, location, item, reason);
    }

    public static void spawnItemsTowardsLocation(Player player, Location source, Location destination, ItemStack item, int amount, double speed, ItemSpawnReason reason) {
        MiscItemSpawner.spawnItemsTowardsLocation(player, source, destination, item, amount, speed, reason);
    }

    public static Item spawnItemTowardsLocation(Player player, Location source, Location destination, ItemStack item, double speed, ItemSpawnReason reason) {
        return MiscItemSpawner.spawnItemTowardsLocation(player, source, destination, item, speed, reason);
    }

    public static boolean isNPCEntityExcludingVillagers(Entity entity) {
        return NPCUtil.isNPCEntityExcludingVillagers(entity);
    }

    public static boolean isNPCClassType(Entity entity) {
        return NPCUtil.isNPCClassType(entity);
    }

    public static boolean hasNPCMetadataTag(Entity entity) {
        return NPCUtil.hasNPCMetadataTag(entity);
    }

    public static boolean isVillager(Entity entity) {
        return NPCUtil.isVillager(entity);
    }

    public static boolean isNPCIncludingVillagers(@Nullable Entity entity) {
        return NPCUtil.isNPCIncludingVillagers(entity);
    }

    private static class SpawnOrbTask implements Runnable {
        private final Location location;
        private int orbExpValue;

        private SpawnOrbTask(Location location, int orbExpValue) {
            this.location = location;
            this.orbExpValue = orbExpValue;
        }

        @Override
        public void run() {
            if (location == null || location.getWorld() == null)
                return;

            ExperienceOrb experienceOrb = (ExperienceOrb) location.getWorld().spawnEntity(location, EntityType.EXPERIENCE_ORB);
            experienceOrb.setExperience(orbExpValue);
        }
    }
}
